export interface ImageAsset {
  section: 'about' | 'branding' | 'other';
  event: string;
  webp: string;
  jpg: string;
  thumbnail: string;
  width: number;
  height: number;
  /**
   * Tiny base64 webp for next/image placeholder="blur". Generated by
   * scripts/sync-images-manifest.mjs. Absent on the graphic-design logos.
   */
  blur?: string;
  alt: string;
  /** The photo EventFeature leads with for its event. One per event. */
  featured?: boolean;
}

/**
 * Decorative backdrops for BackdropBand. Sourced stock photography, never
 * a real event photo, so there is no event/thumbnail/lightbox shape to
 * match. Alt is empty on purpose: BackdropBand always renders these behind
 * foreground text, so they are decorative per WCAG. Never place one inside
 * an EventFeature strip, the TileMarquee, or the lightbox.
 */
export interface StockImage {
  id:
    | 'tablescape'
    | 'buttercream'
    | 'linen'
    | 'nashville'
    | 'tablescape-wide'
    | 'buttercream-wide';
  jpg: string;
  width: number;
  height: number;
  /** Tiny base64 webp for placeholder="blur". Generated by scripts/sync-images-manifest.mjs. */
  blur: string;
  alt: string;
}

